#include <EEPROM.h>

const int AZUL = 2, BOTON = 19;
int estado = 0;
int anterior = HIGH;

void setup() {
  Serial.begin(115200);
  EEPROM.begin(1);
  pinMode(AZUL, OUTPUT);
  pinMode(BOTON, INPUT_PULLUP);
  estado = EEPROM.read(0) == 1 ? 1 : 0;
  digitalWrite(AZUL, estado);
}

void loop() {
  int ahora = digitalRead(BOTON);
  if (anterior == HIGH && ahora == LOW) {
    estado = !estado;
    digitalWrite(AZUL, estado);
    EEPROM.write(0, estado);
    EEPROM.commit();
  }
  anterior = ahora;
  delay(20);
}
